on conflict (k) do update set v = excluded.v;

do $$
declare
  v_ids jsonb := '["dong-phuc", "thanh-sam", "hac-y", "hong-y", "bach-kiem-bao", "tu-liem-y", "huyet-giap", "bi-ngo", "tuyet-lanh", "tien-nhan", "hoang-kim", "tet-do", "thien-mach-bao", "bang-y-han-bang", "luc-bao-thanh-moc", "tho-bao-hau-tho", "than-nguyen-y", "huyet-nguyet", "tu-linh-ma-yeu", "ly-hoa"]';
  r record; v_d jsonb; v_comps jsonb; v_co jsonb; v_k text; v_id text; v_them jsonb;
begin
  for r in select distinct on (x.user_id) x.user_id, x.du_lieu from public.p2d_xu_ly x where x.hanh_dong = 'doi_moi_16_11' order by x.user_id, x.id loop
    v_co := case when jsonb_typeof(r.du_lieu -> 'outfits') = 'object' then r.du_lieu -> 'outfits' else '{}'::jsonb end;
    if coalesce(r.du_lieu ->> 'outfit', '') <> '' then v_co := v_co || jsonb_build_object(r.du_lieu ->> 'outfit', true); end if;
    select data into v_d from public.p2d_nhan_vat where user_id = r.user_id for update;
    continue when v_d is null;
    v_comps := case when jsonb_typeof(v_d -> 'comps') = 'object' then v_d -> 'comps' else '{}'::jsonb end;
    v_them := '[]'::jsonb;
    for v_k in select jsonb_object_keys(v_co) loop
      v_id := split_part(v_k, ':', 1);
      if v_ids ? v_id and not (v_comps ? ('kl-' || v_id)) and not (v_them ? ('kl-' || v_id)) then
        v_comps := v_comps || jsonb_build_object('kl-' || v_id, '{"lv": 1, "exp": 0}'::jsonb);
        v_them := v_them || jsonb_build_array('kl-' || v_id);
      end if;
    end loop;
    continue when v_them = '[]'::jsonb;
    insert into public.p2d_xu_ly (user_id, hanh_dong, du_lieu) values (r.user_id, 'do_cu_khoi_loi', jsonb_build_object('them', v_them));
    update public.p2d_nhan_vat set data = jsonb_set(jsonb_set(v_d, '{comps}', v_comps), '{quaKL17}', v_them) where user_id = r.user_id;
  end loop;
end $$;
